// gitReadSaidLimit bounds what a read error keeps of Git's standard error.
const gitReadSaidLimit = 600

// GitReadError describes a failed git read with what git said on standard
// error, all of it on one line and bounded, so a warning Git prints first
// does not hide the cause (review round 3, N17). It does not guess from the
// words whether the index was at fault: ErrIndexUnreadable marks only the
// failures of ReadOnlyIndex itself (review rounds 2 N13, 3 N18).
func GitReadError(what string, err error, stderr []byte) error {
	// Git's fatal and error lines first, so a long warning before them does
	// not push the cause past the bound (review round 4, N25).
	var first, rest []string
	for _, line := range strings.Split(string(stderr), "\n") {
		line = strings.Join(strings.Fields(line), " ")
		switch {
		case line == "":
		case strings.HasPrefix(line, "fatal:") || strings.HasPrefix(line, "error:"):
			first = append(first, line)
		default:
			rest = append(rest, line)
		}
	}
	said := strings.Join(append(first, rest...), " ; ")
	said = TruncateUTF8(said, gitReadSaidLimit)
	if said == "" {
		return fmt.Errorf("%s failed: %w", what, err)
	}
	return fmt.Errorf("%s failed: %w: %s", what, err, said)
}

// GitEnglish makes cmd's messages English, so the causes reported read the
// same in every locale.
func GitEnglish(cmd *exec.Cmd) {
	cmd.Env = append(cmd.Env, "LC_ALL=C", "LANGUAGE=C")
}

// privateIndexCopy hands raw to cmd as a private copy: Git refreshes and may
// rewrite the copy, never the checkout's index.
func privateIndexCopy(cmd *exec.Cmd, raw []byte, modTime time.Time) (func(), error) {
	dir, err := os.MkdirTemp("", "pose-index-*")
	if err != nil {
		return func() {}, err
	}
	done := func() { _ = os.RemoveAll(dir) }
	path := filepath.Join(dir, "index")
	if err := os.WriteFile(path, raw, 0o600); err != nil {
		done()
		return func() {}, err
	}
	if err := os.Chtimes(path, modTime, modTime); err != nil {
		done()
		return func() {}, err
	}
	// A split index would write a new shared index into .git.
	cmd.Args = append([]string{cmd.Args[0], "-c", "core.splitIndex=false"}, cmd.Args[1:]...)
	cmd.Env = append(cmd.Env, "GIT_INDEX_FILE="+path)
	return done, nil
}

// RawGitDiffReadOnly runs RawGit(args...), a diff of the repository at root,
// reading its index without writing it, and returns its standard output.
func RawGitDiffReadOnly(root string, args ...string) ([]byte, error) {
	cmd := RawGit(args...)
	done, err := ReadOnlyIndex(cmd, root)
	defer done()
	if err != nil {
		return nil, err
	}
	var stderr bytes.Buffer
	cmd.Stderr = &stderr
	out, err := cmd.Output()
	if err != nil {
		return nil, GitReadError("git diff", err, stderr.Bytes())
	}
	return out, nil
}

