	if since != "" {
		output, err = posemodel.RawGitDiffReadOnly(root, args...)
	} else {
		var stderr bytes.Buffer
		cmd := posemodel.RawGit(args...)
		posemodel.GitEnglish(cmd)
		cmd.Stderr = &stderr
		if output, err = cmd.Output(); err != nil {
			err = posemodel.GitReadError("git status", err, stderr.Bytes())
		}
	}
	if err != nil {
		return nil, err
	}
	files := []string{}
	// Trim only the trailing newline: in porcelain output a leading space is
	// part of the first line's status, and trimming it shifted the path cut
	// below by one character.
	for _, line := range strings.Split(strings.TrimRight(string(output), "\n"), "\n") {
		if line == "" {
			continue
		}
		if since == "" && len(line) >= 4 {
			line = line[3:]
		}
		files = append(files, line)
	}
	return files, nil
}

